import { jsPDF } from 'jspdf';
const font =
  '';
var callAddFont = function () {
  this.addFileToVFS('YeZiGongChangWanNengHeiTi-2-normal.ttf', font);
  this.addFont(
    'YeZiGongChangWanNengHeiTi-2-normal.ttf',
    'YeZiGongChangWanNengHeiTi-2',
    'normal'
  );
};
jsPDF.API.events.push(['addFonts', callAddFont]);
